import React, { Component } from "react";
import { MDBDataTable } from "mdbreact";
import { Card, CardBody, CardHeader, Button, Input } from "reactstrap";
import {
  MdAddCircle,
  MdCheckCircle,
  MdEdit,
  MdRemoveCircle
} from "react-icons/md";
import { connect } from "react-redux";
import axios from "axios";
import { tokenConfig } from "../../actions/authActions";

import store from "../../store";
class Clients extends Component {
  state = {
    addRow: false,
    rowData: [
      {
        id: "01",
        clientName: "General Electric",
        createdBy: "David Henry",
        actions: (
          <div>
            <Button className="float-left" color="dark" onClick={this.addRow}>
              <MdEdit />
            </Button>
            <Button
              className="float-left"
              color="dark"
              style={{ marginLeft: "0.2rem" }}
              onClick={this.removeClients}
            >
              <MdRemoveCircle />
            </Button>
          </div>
        )
      }
    ]
  };
  retrieveClients = () => {
    //this.props.getClients();
    console.log("retrieve");
    axios
      .get("/api/items")
      .then(res => {
        const aR = this.state.rowData;
        this.setState(state => ({
          addRow: state.addRow,
          rowData: aR
        }));
      })
      .catch(err => console.log(err));
  };
  addClient = () => {
    console.log("add");

    const newClient = {
      name: "test client",
      userId: this.props.auth.isAuthenticated
        ? this.props.auth.user.id
        : "Guest"
    };
    axios
      .post("/api/clients", newClient, tokenConfig(store.getState))
      .then(res => console.log(res.data))
      .catch(err => console.log(err.data));
  };

  removeClient = () => {
    console.log("remove");
  };

  addRow = () => {
    const aR = this.state.rowData;
    if (!this.state.addRow) {
      aR.unshift({
        id: "Auto Generated",
        clientName: <Input></Input>,
        createdBy: this.props.auth.isAuthenticated
          ? this.props.auth.user.name
          : "Guest",
        actions: (
          <div>
            <Button
              className="float-left"
              color="dark"
              onClick={this.addClient}
            >
              <MdCheckCircle />
            </Button>
          </div>
        )
      });
    } else {
      aR.splice(0, 1);
    }

    this.setState(state => ({
      addRow: !state.addRow,
      rowData: aR
    }));
  };
  render() {
    const data = {
      columns: [
        {
          label: "Id",
          field: "id",
          sort: "asc",
          width: 50
        },
        {
          label: "Client Name",
          field: "clientName",
          sort: "asc",
          width: 50
        },
        {
          label: "Created By",
          field: "createdBy",
          sort: "asc",
          width: 50
        },
        {
          label: "Actions",
          field: "actions",
          sort: "asc",
          width: 50
        }
      ],
      rows: this.state.rowData
    };

    return (
      <Card>
        <CardHeader>
          <h4 className="float-left">Clients</h4>
          <Button className="float-right" color="dark" onClick={this.addRow}>
            <MdAddCircle />
          </Button>
        </CardHeader>
        <CardBody>
          <MDBDataTable striped bordered hover data={data} />
        </CardBody>
      </Card>
    );
  }
}

const mapStateToProps = state => ({
  //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
  auth: state.auth
});

//export default connect(mapStateToProps, {postClient,getClients,deleteClient})(Clients);
export default connect(mapStateToProps, null)(Clients);
